<script lang="ts">
	import type { BulkRow } from '$lib/ui-types';
	import ModalHeader from '$lib/components/ModalHeader.svelte';
	import ModalShell from '$lib/components/ModalShell.svelte';
	let { laneName, rowsText, startText, length, preview, closeLabel, cancelLabel, createLabel, previewLabel, formatMinute, normalizeTime, onRowsTextChange, onStartTextChange, onLengthChange, onPreviewChange, onClose, onPreview, onCommit }: { laneName: string; rowsText: string; startText: string; length: number; preview: BulkRow[]; closeLabel: string; cancelLabel: string; createLabel: string; previewLabel: string; formatMinute: (minute: number) => string; normalizeTime: (event: FocusEvent, commit: (value: string) => void) => void; onRowsTextChange: (value: string) => void; onStartTextChange: (value: string) => void; onLengthChange: (value: number) => void; onPreviewChange: (value: BulkRow[]) => void; onClose: () => void; onPreview: () => void; onCommit: () => void } = $props();
</script>
<ModalShell className="bulk-modal" labelledBy="bulk-title" {onClose}>
	<ModalHeader eyebrow={`BULK ENTRY · ${laneName}`} title="固定長で一括入力" titleId="bulk-title" closeLabel={closeLabel} {onClose} />
	{#if !preview.length}<div class="form-grid"><label>開始時刻<input value={startText} oninput={(event) => onStartTextChange((event.currentTarget as HTMLInputElement).value)} onblur={(event) => normalizeTime(event, onStartTextChange)} /></label><label>1件の長さ（分）<input type="number" min="5" step="5" value={length} oninput={(event) => onLengthChange(Number((event.currentTarget as HTMLInputElement).value))} /></label></div><label class="bulk-list-label">アーティスト名（1行に1組）<textarea value={rowsText} oninput={(event) => onRowsTextChange((event.currentTarget as HTMLTextAreaElement).value)} placeholder="青空クラブ&#10;月曜日の秘密&#10;Sweet Alley"></textarea></label><div class="modal-actions"><span></span><button class="quiet-button" onclick={onClose}>{cancelLabel}</button><button class="primary-button" onclick={onPreview}>{previewLabel}</button></div>{:else}<div class="preview-table"><div class="preview-head"><span>ARTIST</span><span>START</span><span>END</span></div>{#each preview as row (row.id)}<div class="preview-row"><input value={row.artist} oninput={(event) => onPreviewChange(preview.map((candidate) => candidate.id === row.id ? { ...candidate, artist: (event.currentTarget as HTMLInputElement).value } : candidate))} /><input value={formatMinute(row.start)} onblur={(event) => normalizeTime(event, (value) => onPreviewChange(preview.map((candidate) => candidate.id === row.id ? { ...candidate, start: Number(value.slice(0, 2)) * 60 + Number(value.slice(3)) } : candidate)))} /><input value={formatMinute(row.end)} onblur={(event) => normalizeTime(event, (value) => onPreviewChange(preview.map((candidate) => candidate.id === row.id ? { ...candidate, end: Number(value.slice(0, 2)) * 60 + Number(value.slice(3)) } : candidate)))} /></div>{/each}</div><div class="modal-actions"><button class="quiet-button" onclick={() => onPreviewChange([])}>← 戻る</button><span></span><button class="primary-button" onclick={onCommit}>{createLabel}</button></div>{/if}
</ModalShell>
